112	    /**
113	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
114	     * statement (not while PENDING), else the live due; null when it has none.
115	     */
116	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
117	        if (isFrozen(claim)) {
118	            return claim.getSettledDue();
119	        }
120	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
121	                : due(sheetId, person, claim);
122	    }
123	
124	    /** Whether the claim's figure is the due fixed when settled: SETTLED, or VOID once settled. */
125	    private static boolean isFrozen(Claim claim) {
126	        return claim.getStatus() == ClaimStatus.SETTLED
127	                || (claim.getStatus() == ClaimStatus.VOID && claim.getSettledDue() != null);
128	    }
129	
130	    /**
131	     * A claim's due on the sheet's today: the due fixed when settled, else its figure with its late
132	     * charge added on top, raised to the floor (see {@link LateCharge}); null when it has none.
133	     */
134	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
135	        if (isFrozen(claim)) {
136	            return claim.getSettledDue();
137	        }
138	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, person.gradeOn(claim.getDate()), figure(sheetId, person, claim));
139	    }
140	
141	    /**
142	     * A claim's due-by, fixed at creation: its date plus the first of the person's own terms, the
143	     * terms of their grade and the sheet's terms, each as in force on its date, counted in business
144	     * days: skipping every Saturday, Sunday and holiday on the sheet.
145	     */
146	    private LocalDate dueBy(String sheetId, LocalDate dated, int terms) {
147	        return holidays.businessDaysAfter(sheetId, dated, terms);
148	    }
149	
150	    /** The terms a claim of the person dated so is due by: their own, else those of their grade or the sheet. */
151	    private int terms(String sheetId, Person person, LocalDate dated) {
152	        Integer own = person.getTerms();
153	        return own != null ? own : sheets.sheet(sheetId).termsFor(person.gradeOn(dated), dated);
154	    }
