161	    @Transactional
162	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
163	            String corrects, String ref, List<String> tags) {
164	        roles.refuseViewer(sheetId, user);
165	        Person person = person(sheetId, personId);
166	        LocalDate dated = dateOrToday(sheetId, date);
167	        int terms = terms(sheetId, person, dated);
168	        LocalDate dueBy = dueBy(sheetId, dated, terms);
169	        periods.refuseIfClosed(sheetId, dueBy);
170	        refuseIfRetired(person, dated);
171	        String corrected = corrected(sheetId, personId, amount, corrects);
172	        refuseIfRefUsed(sheetId, ref, null);
173	        RollupService.Snapshot before = rollup.snapshot(sheetId);
174	        Claim claim = new Claim(sheetId, personId, amount, dated, dueBy, terms, note, corrected);
175	        claim.setRef(ref);
176	        claim.setTags(tags);
177	        claim.setLateEntry(periods.isSoftClosed(sheetId, dueBy));
178	        logStatus(sheetId, user, person, claim);
179	        Claim added = claims.saveAndFlush(claim);
180	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added)
181	                + (added.getRef() != null ? " ref=" + added.getRef() : "")
182	                + (added.getTags().isEmpty() ? "" : " tags=" + String.join(",", added.getTags())));
183	        useTags(sheetId, added);
184	        if (added.isLateEntry()) {
185	            audit.recordOnCommit(record("LATE_ENTRY", sheetId, user, person, added));
186	        }
187	        rollup.recordChanges(sheetId, user, before);
188	        return added;
189	    }
