191	    /**
192	     * Whether the claim form would take a claim of the person dated so, as far as its date decides:
193	     * its due-by is inside no closed period and the person's retirements do not refuse the date.
194	     */
195	    @Transactional(readOnly = true)
196	    public boolean takesDate(String sheetId, long personId, LocalDate date) {
197	        Person person = person(sheetId, personId);
198	        LocalDate dueBy = dueBy(sheetId, date, terms(sheetId, person, date));
199	        return !periods.isClosed(sheetId, dueBy) && !person.refusesClaimOn(date);
200	    }
