202	    @Transactional
203	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
204	            String corrects, String ref, List<String> tags) {
205	        roles.refuseViewer(sheetId, user);
206	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
207	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
208	        refuseIfNotEditable(sheetId, user, claim);
209	        LocalDate dated = dateOrToday(sheetId, date);
210	        periods.refuseIfClosed(sheetId, claim.getDueBy());
211	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
212	        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
213	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
214	                    "A claim with lines takes its amount from them.");
215	        }
216	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
217	        refuseIfRefUsed(sheetId, ref, claim.getId());
218	        RollupService.Snapshot before = rollup.snapshot(sheetId);
219	        claim.setAmount(amount);
220	        claim.setRef(ref);
221	        claim.setTags(tags);
222	        claim.setDate(dated);
223	        claim.setNote(note);
224	        claim.setCorrects(corrected);
225	        claim.setLockedBy(null);
226	        claim.setEditedBy(user);
227	        Claim saved = claims.saveAndFlush(claim);
228	        useTags(sheetId, saved);
229	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
230	        rollup.recordChanges(sheetId, user, before);
231	        return saved;
232	    }
