234	    /**
235	     * Change a DRAFT claim's amount in its row, keeping its date, note and correction: refused
236	     * exactly as the claim form's save is, and recorded as CLAIM_EDITED as it is. An editor the
237	     * user has open on the claim stays open.
238	     */
239	    @Transactional
240	    public Claim updateAmount(String sheetId, String user, long id, BigDecimal amount) {
241	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
242	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
243	        String lockedBy = claim.getLockedBy();
244	        Claim saved = update(sheetId, user, id, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
245	                claim.getRef(), claim.getTags());
246	        saved.setLockedBy(lockedBy);
247	        return claims.saveAndFlush(saved);
248	    }
