250	    /**
251	     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
252	     * cancelled, or the sheet's today changes. Refused (403) for a viewer, (409) for a claim that is
253	     * not DRAFT or is locked by another user, and (423) when dated inside a closed period; a refused
254	     * claim takes no lock. Any other claim of the same person the user had locked is released.
255	     */
256	    @Transactional
257	    public Claim lock(String sheetId, String user, long id) {
258	        roles.refuseViewer(sheetId, user);
259	        // hold the sheet so two users cannot both take the lock
260	        sheets.lock(sheetId);
261	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
262	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
263	        refuseIfNotEditable(sheetId, user, claim);
264	        periods.refuseIfClosed(sheetId, claim.getDueBy());
265	        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())) {
266	            if (other.getId() != id && user.equals(other.getLockedBy())) {
267	                other.setLockedBy(null);
268	                claims.save(other);
269	            }
270	        }
271	        claim.setLockedBy(user);
272	        return claims.saveAndFlush(claim);
273	    }
274	
275	    /** Cancel a claim's editor: the user's lock on the claim is released; another user's lock stays. */
276	    @Transactional
277	    public Claim unlock(String sheetId, String user, long id) {
278	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
279	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
280	        if (user.equals(claim.getLockedBy())) {
281	            claim.setLockedBy(null);
282	            claim = claims.saveAndFlush(claim);
283	        }
284	        return claim;
285	    }
