287	    /** Refuse (409) editing a claim that is not DRAFT, or that another user's open editor locks. */
288	    private static void refuseIfNotEditable(String sheetId, String user, Claim claim) {
289	        if (claim.getStatus() != ClaimStatus.DRAFT) {
290	            throw new ResponseStatusException(HttpStatus.CONFLICT,
291	                    "A " + claim.getStatus() + " claim cannot be edited.");
292	        }
293	        if (claim.isLockedAgainst(user)) {
294	            throw new ResponseStatusException(HttpStatus.CONFLICT,
295	                    "This claim is being edited by " + claim.getLockedBy() + ".");
296	        }
297	    }
