299	    /**
300	     * Move a claim to a new status, refused (409) when its current status does not allow it,
301	     * refused (403) when the user who opened it tries to settle it, and refused (422) settling a
302	     * claim above the proof threshold with no proofs. A clerk settling one whose
303	     * figure is above the sheet's clerk limit makes it PENDING instead.
304	     */
305	    @Transactional
306	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
307	        return changeStatus(sheetId, user, id, next, null, false, null);
308	    }
309	
310	    /**
311	     * Void a claim, as {@link #changeStatus(String, String, long, ClaimStatus)}, with a reason from
312	     * the sheet's void reasons: while the sheet has any, a void without one of them is refused (422).
313	     */
314	    @Transactional
315	    public Claim voidClaim(String sheetId, String user, long id, String voidReason) {
316	        return changeStatus(sheetId, user, id, ClaimStatus.VOID, null, false, voidReason);
317	    }
