319	    /**
320	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
321	     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
322	     * user who opened it.
323	     */
324	    @Transactional
325	    public Claim approve(String sheetId, String user, long id) {
326	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true, null);
327	    }
328	
329	    /**
330	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
331	     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
332	     */
333	    @Transactional
334	    public Claim reject(String sheetId, String user, long id, String reason) {
335	        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true, null);
336	    }
