338	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
339	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
340	            boolean review, String voidReason) {
341	        roles.refuseViewer(sheetId, user);
342	        if (!review) {
343	            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
344	                case OPEN -> "open";
345	                case SETTLED -> "settle";
346	                case VOID -> "void";
347	                default -> throw new IllegalStateException();
348	            });
349	        }
350	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
351	        if (next == ClaimStatus.OPEN) {
352	            sheets.lock(sheetId);
353	        }
354	        RollupService.Snapshot before = rollup.snapshot(sheetId);
355	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
356	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
357	        ClaimStatus was = claim.getStatus();
358	        // only a steward's review moves a PENDING claim on, other than voiding it
359	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
360	            throw new ResponseStatusException(HttpStatus.CONFLICT,
361	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
362	        }
363	        periods.refuseIfClosed(sheetId, claim.getDueBy());
364	        boolean reversing = was == ClaimStatus.SETTLED;
365	        if (reversing) {
366	            refuseVoidSettled(sheetId, user, claim);
367	        }
368	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
369	            throw new ResponseStatusException(HttpStatus.CONFLICT,
370	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
371	        }
372	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
373	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
374	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
375	        }
376	        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
377	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
378	                    "The user who last edited a claim cannot " + (review ? "approve" : "settle") + " it.");
379	        }
380	        if (review && !isSteward(sheetId, user)) {
381	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
382	                    "Only a steward can approve or reject a PENDING claim.");
383	        }
384	        String voidedWith = next == ClaimStatus.VOID ? voidReasons.refuseUnlessListed(sheetId, voidReason) : null;
385	        Person person = person(sheetId, claim.getPersonId());
386	        if (next == ClaimStatus.OPEN && !review && atPeriodCap(sheetId, claim)) {
387	            throw new ResponseStatusException(HttpStatus.CONFLICT,
388	                    "This person already has as many open claims in that period as it allows.");
389	        }
390	        if (next == ClaimStatus.OPEN && !review && needsNote(sheetId, person, claim)) {
391	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
392	                    "A claim due above the note threshold cannot be opened with an empty note.");
393	        }
394	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
395	        // PENDING claim's figure is live)
396	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
397	        if (next == ClaimStatus.SETTLED && needsProof(sheetId, person, claim, settling)) {
398	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
399	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
400	                            + " without a proof.");
401	        }
402	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
403	            next = ClaimStatus.PENDING;
404	            settling = null;
405	        }
406	        claim.setStatus(next);
407	        if (next == ClaimStatus.OPEN && !review) {
408	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
409	            claim.setOpenedBy(user);
410	        } else if (next == ClaimStatus.SETTLED) {
411	            claim.setSettledDue(settling);
412	        } else if (next == ClaimStatus.VOID) {
413	            claim.setVoidReason(voidedWith);
414	        }
415	        logStatus(sheetId, user, person, claim);
416	        Claim saved = claims.saveAndFlush(claim);
417	        String event = switch (next) {
418	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
419	            case PENDING -> "CLAIM_PENDING";
420	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
421	            case VOID -> "CLAIM_VOIDED";
422	            case DRAFT, DELETED -> throw new IllegalStateException();
423	        };
424	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
425	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
426	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
427	                + (reason != null ? " reason=" + reason : "")
428	                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : "")
429	                + (voidedWith != null ? " reason=" + voidedWith : ""));
430	        if (next == ClaimStatus.SETTLED) {
431	            notifyWatchers(sheetId, user, person, saved);
432	        }
433	        rollup.recordChanges(sheetId, user, before);
434	        return saved;
435	    }
