437	    /**
438	     * Delete a DRAFT claim: it becomes DELETED, counts nowhere and makes no other move but a restore;
439	     * its status log gains a DELETED line and CLAIM_DELETED is written. Any editor's lock on it is
440	     * released. Refused (403) for a viewer, (409) for a claim that is not DRAFT or that another
441	     * user's open editor locks, and (423) when due inside a closed period.
442	     */
443	    @Transactional
444	    public Claim delete(String sheetId, String user, long id) {
445	        roles.refuseViewer(sheetId, user);
446	        RollupService.Snapshot before = rollup.snapshot(sheetId);
447	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
448	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
449	        if (!claim.getStatus().canBecome(ClaimStatus.DELETED)) {
450	            throw new ResponseStatusException(HttpStatus.CONFLICT,
451	                    "A " + claim.getStatus() + " claim cannot be deleted.");
452	        }
453	        if (claim.isLockedAgainst(user)) {
454	            throw new ResponseStatusException(HttpStatus.CONFLICT,
455	                    "This claim is being edited by " + claim.getLockedBy() + ".");
456	        }
457	        periods.refuseIfClosed(sheetId, claim.getDueBy());
458	        Person person = person(sheetId, claim.getPersonId());
459	        claim.setStatus(ClaimStatus.DELETED);
460	        claim.setLockedBy(null);
461	        logStatus(sheetId, user, person, claim);
462	        Claim saved = claims.saveAndFlush(claim);
463	        audit.recordOnCommit(record("CLAIM_DELETED", sheetId, user, person, saved));
464	        rollup.recordChanges(sheetId, user, before);
465	        return saved;
466	    }
467	
468	    /**
469	     * Restore a DELETED claim to DRAFT, on the sheet-today it was deleted (the date its status log
470	     * records it DELETED): its log gains a DRAFT line and CLAIM_RESTORED is written. Refused (403)
471	     * for a viewer, (409) for a claim that is not DELETED or on a later (or earlier) sheet-today, and
472	     * (423) when due inside a closed period.
473	     */
474	    @Transactional
475	    public Claim restore(String sheetId, String user, long id) {
476	        roles.refuseViewer(sheetId, user);
477	        RollupService.Snapshot before = rollup.snapshot(sheetId);
478	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
479	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
480	        if (!claim.getStatus().canBecome(ClaimStatus.DRAFT)) {
481	            throw new ResponseStatusException(HttpStatus.CONFLICT,
482	                    "A " + claim.getStatus() + " claim cannot be restored.");
483	        }
484	        LocalDate deleted = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
485	                .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
486	        if (deleted == null || !deleted.equals(sheets.today(sheetId))) {
487	            throw new ResponseStatusException(HttpStatus.CONFLICT,
488	                    "A DELETED claim can be restored only on the day it was deleted.");
489	        }
490	        periods.refuseIfClosed(sheetId, claim.getDueBy());
491	        Person person = person(sheetId, claim.getPersonId());
492	        claim.setStatus(ClaimStatus.DRAFT);
493	        logStatus(sheetId, user, person, claim);
494	        Claim saved = claims.saveAndFlush(claim);
495	        audit.recordOnCommit(record("CLAIM_RESTORED", sheetId, user, person, saved));
496	        rollup.recordChanges(sheetId, user, before);
497	        return saved;
498	    }
499	
500	    /**
501	     * Refuse voiding a SETTLED claim: (403) for anyone but a steward, and (409) once the sheet's
502	     * today is more than {@value #VOID_SETTLED_DAYS} days after its settlement (or before it).
503	     */
504	    private void refuseVoidSettled(String sheetId, String user, Claim claim) {
505	        if (!isSteward(sheetId, user)) {
506	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a SETTLED claim.");
507	        }
508	        LocalDate settled = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
509	                .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
510	        LocalDate today = sheets.today(sheetId);
511	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
512	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can be voided only within "
513	                    + VOID_SETTLED_DAYS + " days of its settlement.");
514	        }
515	    }
