517	    /** Record a notice of the claim for each user watching its person, in the order they started watching. */
518	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
519	        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
520	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUserName()
521	                    + " person=" + person.getName() + " number=" + claim.getNumber());
522	        }
523	    }
