729	    private Claim reassign(String sheetId, String user, long id, long toPersonId, boolean allowSamePerson) {
730	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
731	        // lock the sheet's numbering before reading the claim, as opening one does
732	        sheets.lock(sheetId);
733	        RollupService.Snapshot before = rollup.snapshot(sheetId);
734	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
735	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
736	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
737	                || claim.getStatus() == ClaimStatus.DELETED) {
738	            throw new ResponseStatusException(HttpStatus.CONFLICT,
739	                    "A " + claim.getStatus() + " claim cannot be moved.");
740	        }
741	        Person from = person(sheetId, claim.getPersonId());
742	        Person to = person(sheetId, toPersonId);
743	        if (!allowSamePerson && from.getId().equals(to.getId())) {
744	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
745	        }
746	        if (claim.isCorrection()) {
747	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
748	        }
749	        periods.refuseIfClosed(sheetId, claim.getDueBy());
750	        refuseIfRetired(to, claim.getDate());
751	        // a numbered claim moved (in place too) takes the next number; its old one is not reused
752	        if (claim.getNumber() != null) {
753	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
754	        }
755	        claim.setPersonId(to.getId());
756	        claim.bind(false, null);
757	        claims.saveAndFlush(claim);
758	        claims.listFirst(claim.getId());
759	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
760	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
761	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
762	                + " from=" + from.getName() + " to=" + to.getName());
763	        rollup.recordChanges(sheetId, user, before);
764	        return saved;
765	    }
