771	    /**
772	     * Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from
773	     * any statement; a new OPEN claim with the amount split off, the same date and note, the next
774	     * number, opened by the user and due by its date plus the terms in force on it, is listed first
775	     * under the person and shows the original's number as split-from. Refused (403) for a role that
776	     * may not open a claim, (409) for a claim that is not OPEN or is deferred, (400) for an amount
777	     * not above 0.00 and below the claim's, and (423) when the original is due inside a closed period
778	     * (the split's own due-by is not checked). The split is numbered in, and a late entry of, the
779	     * period of its own due-by.
780	     */
781	    @Transactional
782	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
783	        roles.refuseViewer(sheetId, user);
784	        roles.refuseUnlessPermitted(sheetId, user, "open");
785	        // lock the sheet's numbering before reading the claim, as opening one does
786	        sheets.lock(sheetId);
787	        RollupService.Snapshot before = rollup.snapshot(sheetId);
788	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
789	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
790	        if (claim.getStatus() != ClaimStatus.OPEN) {
791	            throw new ResponseStatusException(HttpStatus.CONFLICT,
792	                    "A " + claim.getStatus() + " claim cannot be split.");
793	        }
794	        if (claim.isDeferredOn(sheets.today(sheetId))) {
795	            throw new ResponseStatusException(HttpStatus.CONFLICT,
796	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then.");
797	        }
798	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
799	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
800	                    "A split must be more than 0.00 and less than the claim's amount.");
801	        }
802	        periods.refuseIfClosed(sheetId, claim.getDueBy());
803	        Person person = person(sheetId, claim.getPersonId());
804	        claim.setAmount(claim.getAmount().subtract(amount));
805	        claim.bind(false, null);
806	        Claim original = claims.saveAndFlush(claim);
807	        LocalDate dated = claim.getDate();
808	        int terms = terms(sheetId, person, dated);
809	        Claim split = new Claim(sheetId, person.getId(), amount, dated, dueBy(sheetId, dated, terms), terms,
810	                claim.getNote(), null);
811	        split.setStatus(ClaimStatus.OPEN);
812	        split.setNumber(sheets.nextClaimNumber(sheetId, split.getDueBy()));
813	        split.setLateEntry(periods.isSoftClosed(sheetId, split.getDueBy()));
814	        split.setOpenedBy(user);
815	        split.setSplitFrom(original.getNumber());
816	        split.setTags(original.getTags());
817	        logStatus(sheetId, user, person, split);
818	        Claim added = claims.saveAndFlush(split);
819	        audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original)
820	                + " number=" + original.getNumber() + " into=" + added.getNumber());
821	        audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, added) + " number=" + added.getNumber());
822	        rollup.recordChanges(sheetId, user, before);
823	        return new Split(original, added);
824	    }
