826	    /**
827	     * Whether the claim's period (the one its due-by falls in) caps open claims per person and its
828	     * person already has that many OPEN or PENDING claims in it.
829	     */
830	    private boolean atPeriodCap(String sheetId, Claim claim) {
831	        return periods.on(sheetId, claim.getDueBy()).filter(p -> p.getClaimCap() != null)
832	                .map(p -> claims.countBySheetIdAndPersonIdAndStatusInAndDueByBetween(sheetId, claim.getPersonId(),
833	                        List.of(ClaimStatus.OPEN, ClaimStatus.PENDING), p.getFromDate(), p.getToDate()) >= p
834	                                .getClaimCap())
835	                .orElse(false);
