842	    /**
843	     * Open the given claims together, in list order (the order people were added, newest claim
844	     * first within a person), so they are numbered in that order. A claim that cannot be opened
845	     * (not on the sheet, not DRAFT, dated inside a closed period, its person at its period's cap, or due above the note threshold
846	     * with an empty note) is refused and left as it is.
847	     */
848	    @Transactional
849	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
850	        List<Claim> selected = inListOrder(sheetId, ids);
851	        int refused = (int) ids.stream().distinct().count() - selected.size();
852	        List<Claim> opened = new ArrayList<>();
853	        boolean permitted = sheets.sheet(sheetId).permits("open", roles.roleOf(sheetId, user));
854	        for (Claim claim : selected) {
855	            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDueBy())
856	                    || atPeriodCap(sheetId, claim) || needsNote(sheetId, person(sheetId, claim.getPersonId()), claim)) {
857	                refused++;
858	                continue;
859	            }
860	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
861	        }
862	        return new BulkOpened(opened.size(), refused, opened);
863	    }
