866	     * What a bulk settle did: how many claims were settled (or made PENDING) and how many refused,
867	     * the claims changed, and the sheet's last batch number after it (0 when there has been none).
868	     */
869	    public record BulkSettled(int settled, int refused, List<Claim> claims, int lastBatch) {
870	    }
