872	    /**
873	     * Settle the given claims together, all or nothing: in list order (the order people were added,
874	     * newest claim first within a person), each by exactly the rules of settling one claim. A claim
875	     * a clerk's settle makes PENDING counts as settled. When any selected claim cannot be settled
876	     * (or is not on the sheet), none is: every one counts as refused and nothing is written. Else the
877	     * settle is a batch: it takes the sheet's next batch number, each claim is marked with it, and
878	     * after the claims' own records one BATCH_SETTLED record gives the batch, its count and the
879	     * frozen dues of those SETTLED added up.
880	     */
881	    @Transactional
882	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
883	        List<Claim> selected = inListOrder(sheetId, ids);
884	        int requested = (int) ids.stream().distinct().count();
885	        List<Claim> settled = new ArrayList<>();
886	        boolean refusedAny = selected.size() < requested;
887	        for (Claim claim : selected) {
888	            if (refusedAny) {
889	                break;
890	            }
891	            try {
892	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
893	            } catch (ResponseStatusException refusedOne) {
894	                refusedAny = true;
895	            }
896	        }
897	        if (refusedAny || settled.isEmpty()) {
898	            // undo the claims already settled, and the records waiting for the commit with them
899	            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
900	            return new BulkSettled(0, requested, List.of(), sheets.sheet(sheetId).getLastBatch());
901	        }
902	        int batch = sheets.nextBatch(sheetId);
903	        List<Claim> batched = new ArrayList<>();
904	        BigDecimal total = BigDecimal.ZERO;
905	        for (Claim claim : settled) {
906	            claim.setBatch(batch);
907	            batched.add(claims.saveAndFlush(claim));
908	            if (claim.getStatus() == ClaimStatus.SETTLED) {
909	                total = total.add(claim.getSettledDue());
910	            }
911	        }
912	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
913	                + " count=" + batched.size() + " total=" + dueText(total));
914	        return new BulkSettled(batched.size(), 0, batched, batch);
915	    }
