1037	    private LocalDate roundingDate(String sheetId, Claim claim) {
1038	        if (!claim.isCorrection() || claim.getCorrects() == null) {
1039	            return claim.getDate();
1040	        }
1041	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
1042	    }
