1055	     * Whether a claim settling at the figure is above the proof threshold in force on its date (its
1056	     * person's grade's then when it has one, else the sheet's) and has no proofs.
1057	     */
1058	    private boolean needsProof(String sheetId, Person person, Claim claim, BigDecimal figure) {
1059	        BigDecimal threshold = sheets.sheet(sheetId).proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
1060	        return claim.getProofs() == 0 && figure != null && threshold != null && figure.compareTo(threshold) > 0;
1061	    }
