1063	    /** Whether a claim's due is above the note threshold in force on its date and its note is empty. */
1064	    private boolean needsNote(String sheetId, Person person, Claim claim) {
1065	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
1066	            return false;
1067	        }
1068	        BigDecimal threshold = sheets.sheet(sheetId).noteThresholdOn(claim.getDate());
1069	        BigDecimal due = threshold == null ? null : charged(sheetId, person, claim);
1070	        return due != null && due.compareTo(threshold) > 0;
