1074	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
1075	        BigDecimal limit = sheets.clerkLimit(sheetId);
1076	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
1077	    }
