1084	     * The number a claim corrects: none unless its amount is negative, when it must name the number
1085	     * of a SETTLED claim of the same person, else it is refused (400).
1086	     */
1087	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
1088	        if (amount.signum() >= 0) {
1089	            return null;
1090	        }
1091	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
1092	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
1093	        if (!settled) {
1094	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
1095	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
1096	        }
1097	        return corrects;
