1101	     * Refuse (422) a claim dated after its person's retirement date, or after the from-date and
1102	     * before the to-date of one of their past retirements.
1103	     */
1104	    private static void refuseIfRetired(Person person, LocalDate date) {
1105	        if (person.refusesClaimOn(date)) {
1106	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
1107	                    "That claim's date is after its person's retirement date.");
1108	        }
1109	    }
