1117	    void refuseIfRefUsed(String sheetId, String ref, Long exceptId) {
1118	        if (ref != null && (exceptId == null ? claims.existsBySheetIdAndRefIgnoreCase(sheetId, ref)
1119	                : claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, ref, exceptId))) {
1120	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1121	                    "The reference " + ref + " is already used on this sheet.");
1122	        }
1123	    }
1124	
