package net.officefloor.hq.app.rollup;


/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total
 * (the figures of their overdue claims that count, not capped), and the sheet's totals of each. A change takes a {@link #snapshot} before it alters anything
 * and calls {@link #recordChanges} after its own audit lines, which appends one ROLLUP line per
 * person whose figures moved (people in the order they were added; a new person counts as moved),
 * then a TOTALS line when any of the sheet's totals moved. A held person's OPEN claims count in none of
 * these (nor their PENDING ones), nor in a period's due-total; their SETTLED claims still do. So too a person whose
 * retirement date the sheet's today has reached. An overdue claim's figure has
 * its late charge added on top, and a live due is then never below the floor in force on its claim's date. A person's
 * due-total is at most the cap in force on the sheet's today, when there is one. With an alert threshold
 * set, the rollup lines are followed by one ALERT line per person (in list order) whose due-total went
 * from at or below it (or none) to above it.
 */
@Service
public class RollupService {

    /** A person's figures: claimed, due-total (null for n/a) and overdue-total. */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    /** The sheet's figures: each person's by id, in the order they were added. */
    public record Snapshot(Map<Long, Figures> people) {

        public BigDecimal claimedTotal() {
            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
        }

        /** People's due-totals added up (n/a is no figure), trimmed as {@link #trimmed} says. */
        public BigDecimal dueTotal() {
            return trimmed(people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull).toList());
        }

        /** People's overdue-totals added up, trimmed as {@link #trimmed} says. */
        public BigDecimal overdueTotal() {
            return trimmed(people.values().stream().map(Figures::overdueTotal).toList());
        }

        /** The sum of people's figures, leaving out the single highest and lowest when there are three or more. */
        private static BigDecimal trimmed(List<BigDecimal> figures) {
            BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
            if (figures.size() < 3) {
                return sum;
            }
            return sum.subtract(figures.stream().reduce(BigDecimal::max).orElseThrow())
                    .subtract(figures.stream().reduce(BigDecimal::min).orElseThrow());
        }
    }

    /** Figures added up over sheets: their people (retired included), due-totals and overdue-totals. */
    public record Consolidated(int peopleCount, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateChain rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateChain rates, SheetRepository sheets,
            Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheet(sheetId);
        LocalDate today = sheet.getToday();
        List<List<Rate>> sheetRates = rates.current(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean anyFigure = false;
            for (Claim claim : sheetClaims) {
                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim, today)) {
                    continue;
                }
                if (!claim.isCorrection()) {
                    claimed = claimed.add(claim.getAmount());
                }
                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
                if (figure != null) {
                    anyFigure = true;
                    due = due.add(figure);
                    if (overdue(sheet, person, claim)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // as on screen: n/a when the grade in force today has no rate today and no claim that
            // counts has a figure
            boolean none = inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !anyFigure;
            figures.put(person.getId(), new Figures(person.getName(), claimed, none ? null : sheet.capped(due),
                    overdue));
        }
        return new Snapshot(figures);
    }

    /**
     * The figures of the sheet's descendants (its children, their children and so on; not the sheet
     * itself), each sheet's due- and overdue-total as that sheet shows it, added up.
     */
    public Consolidated descendants(String sheetId) {
        Set<String> seen = new HashSet<>(Set.of(sheetId));
        Deque<String> pending = new ArrayDeque<>(List.of(sheetId));
        int count = 0;
        BigDecimal due = zero();
        BigDecimal overdue = zero();
        while (!pending.isEmpty()) {
            for (Sheet child : sheets.findByParentIdOrderByIdAsc(pending.pop())) {
                if (!seen.add(child.getId())) {
                    continue;
                }
                Snapshot figures = snapshot(child.getId());
                count += figures.people().size();
                due = due.add(figures.dueTotal());
                overdue = overdue.add(figures.overdueTotal());
                pending.add(child.getId());
            }
        }
        return new Consolidated(count, due, overdue);
    }

    /**
     * Each person's due of their claims whose due-by falls in from..to (both inclusive) and that
     * counted by the status they had at the end of the to-day (as their status log records it; a
     * claim with none by then does not), by person id, for every person on the sheet (0.00 when
     * none). Each counts at its figure as shown now.
     */
    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
        Sheet sheet = sheet(sheetId);
        List<List<Rate>> sheetRates = rates.current(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<Long, BigDecimal> dues = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            BigDecimal due = zero();
            for (Claim claim : sheetClaims) {
                if (!claim.getPersonId().equals(person.getId()) || claim.getDueBy().isBefore(from)
                        || claim.getDueBy().isAfter(to) || !claim.statusAt(to)
                                .map(status -> person.counts(claim, status, sheet.getToday())).orElse(false)) {
                    continue;
                }
                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
                if (figure != null) {
                    due = due.add(figure);
                }
            }
            dues.put(person.getId(), due);
        }
        return dues;
    }

    /** Record, once the change commits, the figures that moved since the snapshot taken before it. */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        recordChanges(sheetId, user, before, false);
    }

    /** Record, once the change commits, the figures of every person on the sheet in list order, then its totals. */
    public void recordAll(String sheetId, String user) {
        Snapshot now = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        for (Figures figures : now.people().values()) {
            audit.recordOnCommit("ROLLUP" + prefix + " person=" + figures.name() + " claimed="
                    + money(figures.claimed()) + " due-total=" + money(figures.dueTotal()) + " overdue-total="
                    + money(figures.overdueTotal()));
        }
        audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + money(now.claimedTotal()) + " due-total="
                + money(now.dueTotal()) + " overdue-total=" + money(now.overdueTotal()));
        recordAlerts(sheetId, prefix, new Snapshot(Map.of()), now);
    }

    /**
     * Record, once the change commits, the figures that moved since the snapshot taken before it;
     * with {@code leaving}, a person who has left the sheet since counts as moved, so the totals
     * they leave are recorded too.
     */
    public void recordChanges(String sheetId, String user, Snapshot before, boolean leaving) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        boolean moved = leaving && !after.people().keySet().containsAll(before.people().keySet());
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures now = entry.getValue();
            Figures was = before.people().get(entry.getKey());
            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
                    && same(was.overdueTotal(), now.overdueTotal())) {
                continue;
            }
            moved = true;
            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + money(now.claimed())
                    + " due-total=" + money(now.dueTotal()) + " overdue-total=" + money(now.overdueTotal()));
        }
        if (moved && !(same(before.claimedTotal(), after.claimedTotal())
                && same(before.dueTotal(), after.dueTotal()) && same(before.overdueTotal(), after.overdueTotal()))) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + money(after.claimedTotal()) + " due-total="
                    + money(after.dueTotal()) + " overdue-total=" + money(after.overdueTotal()));
        }
        recordAlerts(sheetId, prefix, before, after);
    }

    /**
     * Record one ALERT per person, in list order, whose due-total went from at or below the sheet's
     * alert threshold (or none) to above it; none when the threshold is off.
     */
    private void recordAlerts(String sheetId, String prefix, Snapshot before, Snapshot after) {
        BigDecimal threshold = sheet(sheetId).getAlertThreshold();
        if (threshold == null) {
            return;
        }
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures now = entry.getValue();
            Figures was = before.people().get(entry.getKey());
            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
                audit.recordOnCommit("ALERT" + prefix + " name=" + now.name() + " due-total=" + money(now.dueTotal()));
            }
        }
    }

    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
    }

    /**
     * A claim's figure as the screen shows it: the due fixed when settled, else the one bound by the
     * last statement (not while PENDING), else its live due (rounded as the claim rounds, see {@link Rounding}), with its late charge added on top, then raised to the floor (a correction's is not);
     * null when none.
     */
    private static BigDecimal figure(Sheet sheet, List<List<Rate>> sheetRates, List<Claim> sheetClaims, Person person,
            Claim claim) {
        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal figure = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
                : inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
                        .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2,
                                Rounding.mode(sheet, Rounding.dateOf(claim, sheetClaims))))
                        .orElse(null);
        return LateCharge.withCharge(sheet, claim, person.gradeOn(claim.getDate()), figure);
    }

    /**
     * Whether a claim is overdue on the sheet's today: OPEN or PENDING, not deferred, and past its due-by plus the
     * grace days of its person's grade on its date (see {@link Sheet#lateFrom}).
     */
    private static boolean overdue(Sheet sheet, Person person, Claim claim) {
        LocalDate today = sheet.getToday();
        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null && claim.getDueBy() != null
                && sheet.lateFrom(claim.getDueBy(), claim.getDate(), person.gradeOn(claim.getDate())).isBefore(today);
    }

    private Sheet sheet(String sheetId) {
        return sheets.findById(sheetId).orElseGet(() -> new Sheet(sheetId, null, null, LocalDate.now()));
    }

    /** The grade's rate in force on a date, on the sheet or failing that its nearest ancestor (see {@link RateChain}). */
    private static Optional<Rate> inForce(List<List<Rate>> sheetRates, String grade, LocalDate date) {
        return RateChain.inForce(sheetRates, grade, date);
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String money(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}
package net.officefloor.hq.app.person;


/** A person on a sheet: a name and their grades (A, B or C), each from a from-date, and the date they are retired from, if any;
 * and the holds they have had, each over a span of dates. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded, the first from the beginning of time (no from-date), the others each from a date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedGrade> grades = new ArrayList<>();

    /** The person's own terms in days, or null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased, or null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The person's tags: trimmed, lower-cased, without repeats, sorted and comma separated; none when they have none. */
    @Column(name = "tags")
    private String tags;

    /** Set once retired: the person counts as retired at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The sheet's today when the person was retired; none while not retired. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    /** The person's past retirements, each ended by unretiring them. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
    private List<PastRetirement> pastRetirements = new ArrayList<>();

    /** The person's snapshot lines, oldest first; written by the sheet when its today moves. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_snapshot", joinColumns = @JoinColumn(name = "person_id"))
    @OrderBy("pos")
    private List<PersonSnapshot> snapshots = new ArrayList<>();

    /** The sheet's today when the person was added; none for one added before it was recorded. */
    @Column(name = "added_on")
    private LocalDate addedOn;

    /** The person's OPEN claims dated within a hold, and not bound by a statement, count in no live total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedHold> holds = new ArrayList<>();

    /** The person's aliases, trimmed; each shares the names' uniqueness on the sheet. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias", nullable = false)
    private Set<String> aliases = new HashSet<>();

    /** The person's place in the sheet's list, lowest first. */
    @Column(name = "position", nullable = false)
    private long position;

    /** The sheet the person was transferred from; null when they were not transferred in. */
    @Column(name = "origin_sheet")
    private String originSheet;

    /** Bumped on every save; an edit must carry the version it was made from. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
        this.sheetId = sheetId;
        this.name = name;
        this.addedOn = addedOn;
        this.grades.add(new DatedGrade(null, grade, addedOn));
    }

        return id;
    }

        return sheetId;
    }

    /**
     * The person as they arrive on another sheet: their name, every grade they were given (each with
     * its from-date), their terms, contact, tags and aliases; not their holds or retirement. They carry
     * this sheet as the one they came from.
     */
    public Person transferredTo(String toSheetId) {
        Person copy = new Person();
        copy.sheetId = toSheetId;
        copy.name = name;
        copy.addedOn = addedOn;
        grades.forEach(g -> copy.grades.add(new DatedGrade(g.getFromDate(), g.getGrade(), g.getMadeOn())));
        copy.terms = terms;
        copy.contact = contact;
        copy.tags = tags;
        copy.aliases.addAll(aliases);
        copy.originSheet = sheetId;
        return copy;
    }

        return originSheet;
    }

        return position;
    }

    public void setPosition(long position) {
        this.position = position;
    }

        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, the one from the beginning of time first and then by from-date. */
        return grades.stream().sorted(Comparator.comparing(DatedGrade::getFromDate,
                Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        String found = null;
        for (DatedGrade g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(date)) {
                found = g.getGrade();
            }
        }
        return found;
    }

    /**
     * The grade in force on a date as the person stood at the end of a day: the one with the latest
     * from-date on or before the date, of those recorded while the sheet's today was on or before the day.
     */
    public String gradeOn(LocalDate date, LocalDate asOf) {
        String found = null;
        for (DatedGrade g : getGrades()) {
            if (g.madeBy(asOf) && (g.getFromDate() == null || !g.getFromDate().isAfter(date))) {
                found = g.getGrade();
            }
        }
        return found;
    }

    /**
     * Record the grade from a date, replacing any grade already recorded from that same date;
     * {@code madeOn} is the sheet's today.
     */
    public void setGradeFrom(LocalDate fromDate, String grade, LocalDate madeOn) {
        grades.removeIf(g -> fromDate.equals(g.getFromDate()));
        grades.add(new DatedGrade(fromDate, grade, madeOn));
    }

        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    /** The person's tags, sorted; empty when they have none. */
        return tags == null ? List.of() : List.of(tags.split(","));
    }

    /** Give the person tags, already trimmed, lower-cased, without repeats and sorted. */
    public void setTags(List<String> tags) {
        this.tags = tags.isEmpty() ? null : String.join(",", tags);
    }

        return retiredFrom;
    }

    /** Retire the person from a date; {@code madeOn} is the sheet's today. */
    public void setRetiredFrom(LocalDate retiredFrom, LocalDate madeOn) {
        this.retiredFrom = retiredFrom;
        this.retiredOn = madeOn;
    }

    /**
     * Unretire the person on a day (the sheet's today): they are no longer retired, and the
     * retirement is kept as a past one from its from-date to that day.
     */
    public void unretire(LocalDate on) {
        pastRetirements.add(new PastRetirement(retiredFrom, on, retiredOn));
        this.retiredFrom = null;
        this.retiredOn = null;
    }

    /** The snapshot lines, oldest first. */
        return List.copyOf(snapshots);
    }

    /** The past retirements, by from-date and then to-date. */
        return pastRetirements.stream().sorted(Comparator.comparing(PastRetirement::getFromDate)
                .thenComparing(PastRetirement::getToDate)).toList();
    }

    /**
     * Whether a claim can be dated on a day: not after the retirement date while retired, nor after
     * the from-date and before the to-date of a past retirement.
     */
    public boolean refusesClaimOn(LocalDate date) {
        return (retiredFrom != null && date.isAfter(retiredFrom))
                || pastRetirements.stream().anyMatch(r -> r.excludes(date));
    }

    /** Whether the person had been added by the end of a day: the sheet's today then on or before it. */
    public boolean addedBy(LocalDate day) {
        return addedOn == null || !addedOn.isAfter(day);
    }

        return retiredFrom != null;
    }

    /** Whether the retirement date is reached on a day (the day on or after it). */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** The holds recorded, by from-date. */
    /** The person's aliases, sorted as names are compared: without regard to case. */
        return aliases.stream().sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT))
                .thenComparing(Comparator.naturalOrder())).toList();
    }

    public void addAlias(String alias) {
        aliases.add(alias);
    }

        return holds.stream().sorted(Comparator.comparing(DatedHold::getFromDate)
                .thenComparing(DatedHold::getToDate, Comparator.nullsLast(Comparator.naturalOrder()))).toList();
    }

    /** Add a hold; {@code madeOn} is the sheet's today. */
    public void addHold(LocalDate fromDate, LocalDate toDate, LocalDate madeOn) {
        holds.add(new DatedHold(fromDate, toDate, madeOn));
    }

    /** Whether the person has any hold. */
        return !holds.isEmpty();
    }

    /** Whether a day lies within one of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /**
     * Whether a claim of this person counts toward the live totals: an open claim dated within a
     * hold does not, nor does one of a person whose retirement date the sheet's today has reached,
     * unless a statement binds it; nor does a claim deferred on the sheet's today.
     */
    public boolean counts(Claim claim, LocalDate today) {
        return counts(claim, claim.getStatus(), today);
    }

    /**
     * Whether a claim of this person counts by the same rules, had it the given status; a hold or a
     * reached retirement takes out only a claim that is open now as well (one since settled or voided is not).
     */
    public boolean counts(Claim claim, ClaimStatus status, LocalDate today) {
        return status.counts() && !claim.isDeferredOn(status, today) && (claim.isStated()
                || !(status.isOpen() && claim.getStatus().isOpen() && (heldOn(claim.getDate()) || retiredOn(today))));
    }

    /**
     * Whether a claim of this person counted at the end of a day, as the person stood then: had it
     * the given status then, and was it bound by a statement then ({@code stated}). The day stands in
     * for the sheet's today, and only holds and a retirement recorded while the sheet's today was on
     * or before it count.
     */
    public boolean countedAsOf(Claim claim, ClaimStatus status, LocalDate day, boolean stated) {
        boolean held = holds.stream().anyMatch(h -> h.madeBy(day) && h.covers(claim.getDate()));
        boolean retired = (retiredFrom != null && (retiredOn == null || !retiredOn.isAfter(day))
                && !day.isBefore(retiredFrom)) || pastRetirements.stream().anyMatch(r -> r.retiredAsOf(day));
        return status.counts() && !claim.isDeferredAsOf(status, day)
                && (stated || !(status.isOpen() && (held || retired)));
    }

        return version;
    }
}

