/**
 * What is due on an amount in whole cents at a percent: cents times the rate divided by 100,
 * rounded to whole cents half to even, or half up when `halfUp` (a negative amount rounds as its
 * opposite does, negated). Null when there is no rate.
 */
export function dueCents(amountCents: number, pct: string | undefined, halfUp = false): number | null {
  if (pct === undefined) return null;
  // cents x rate-in-hundredths-of-a-percent is 10000 times the due in cents
  const scaled = BigInt(Math.abs(amountCents)) * BigInt(cents(pct));
  const whole = scaled / 10000n;
  const rest = scaled % 10000n;
  const due = Number(rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole);
  return amountCents < 0 ? -due : due;
}

/**
 * A claim's fixed figure in whole cents: the one bound by the person's last statement, else the
 * due fixed when it was settled. Null when it has none (its figure is live, or there was no rate).
 */
export function fixedDueCents(c: Claim): number | null {
  const fixed = c.stated && c.status !== 'PENDING' ? c.statedDue : c.settledDue;
  return fixed !== null ? cents(fixed) : null;
}

/**
 * Whether a claim's live figures round half up: it rounds by a date (see `roundingDate`) before
 * the sheet's policy date, the sheet's today when the policy date is blank. On or after it, they
 * round half to even.
 */
export function roundsHalfUp(roundOn: string, policyDate: string, today: string | null): boolean {
  const policy = policyDate !== '' ? policyDate : today;
  return policy !== null && roundOn < policy;
}

/**
 * A claim's figure in whole cents: a stated claim's figure bound by the last statement (not while
 * PENDING: its figure is live), a settled
 * claim's due fixed when it was settled, any other claim's live due at the rate for the grade in
 * force on the claim's date, rounded half up when `halfUp` (else half to even). The floor is not
 * applied here (see {@link chargedDueCents}). Null when it has none.
 */
export function claimDueCents(c: Claim, rates: readonly Rate[], grade: string, halfUp = false): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  if (c.stated && c.status !== 'PENDING') return fixedDueCents(c);
  return dueCents(cents(c.amount), pctOn(rates, grade, c.date), halfUp);
}

/** One value recorded for a dated setting: in force from its from-date (blank: from the
 *  beginning of time) until the next. A blank value is none (no limit, no cap). */
export interface DatedValue {
  from: string;
  value: string;
}

/**
 * The value of a dated setting in force on a date (yyyy-mm-dd): the one with the latest from-date
 * on or before it, one from the beginning of time counting as the earliest. `start` before every
 * from-date.
 */
export function valueOn(values: readonly DatedValue[], date: string | null, start: string): string {
  let best: DatedValue | undefined;
  for (const v of values) {
    if (v.from !== '' && (date === null || v.from > date)) continue;
    if (best === undefined || best.from < v.from) best = v;
  }
  return best?.value ?? start;
}

/** The floor a sheet starts with: in force before its first recorded floor. */
export const START_FLOOR = '1.00';

/** The late percent a sheet starts with: in force before its first recorded late percent. */
export const START_LATE_PCT = '0.00';

/** The grace days of a grade in force on a date (yyyy-mm-dd), from each grade's dated grace days
 *  (a blank value: none); 0 when it has none then. */
export function graceOn(graces: Readonly<Record<string, readonly DatedValue[]>>, grade: string, date: string | null): number {
  const days = valueOn(graces[grade] ?? [], date, '');
  return days === '' ? 0 : Number(days);
}

/** What works out an overdue claim's late charge and rounding: the sheet's late percents (each
 *  claim's is the one in force on its date), each grade's grace days (a claim's are those of its
 *  person's grade on its date, in force on its date), today and policy date (blank: the sheet's today). */
export interface Lateness {
  latePcts: readonly DatedValue[];
  graces: Readonly<Record<string, readonly DatedValue[]>>;
  today: string | null;
  policyDate: string;
}

/**
 * A claim's due in whole cents as shown: its figure (see {@link claimDueCents}) with, when it is
 * overdue, a late charge added on top: for each full 30 days overdue, the late percent in force on
 * that boundary date (its due-by plus its grace days, plus 30, 60, 90 ... days) of that figure plus the charges of the boundaries before it, rounded to whole cents,
 * the charges added up. Both round as the claim rounds by `roundOn` (see {@link roundsHalfUp}).
 * The floor is applied last: the due is the greater of the floor in force on the claim's date and
 * the figure plus its charge. The charge is never bound by a statement; a settled claim's due is
 * frozen as it was settled, and a correction has no floor and no charge. Null when it has no figure.
 */
export function chargedDueCents(
  c: Claim,
  rates: readonly Rate[],
  grade: string,
  floors: readonly DatedValue[],
  late: Lateness,
  roundOn: string,
): number | null {
  const halfUp = roundsHalfUp(roundOn, late.policyDate, late.today);
  const figure = claimDueCents(c, rates, grade, halfUp);
  if (figure === null || c.settledDue !== null || isCorrection(c)) return figure;
  const floor = cents(valueOn(floors, c.date, START_FLOOR));
  if (!isOpen(c)) return Math.max(figure, floor);
  const grace = graceOn(late.graces, grade, c.date);
  const periods = Math.floor(daysOverdue(c, late.today, grace) / 30);
  let charge = 0;
  for (let k = 1; k <= periods; k++) {
    const boundary = plusDays(dueBy(c), grace + 30 * k);
    charge += dueCents(figure + charge, valueOn(late.latePcts, boundary, START_LATE_PCT), halfUp) ?? 0;
  }
  return Math.max(figure + charge, floor);
}

/** A due in whole cents with two decimals, or n/a when there is no rate. */
export function dueText(c: number | null): string {
  return c === null ? 'n/a' : money(c);
}

@Component({
  selector: 'app-rates',
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form aria-label="Rate" (submit)="save($event)">
        <label for="rate-form-grade">Grade</label>
        <select
          id="rate-form-grade"
          data-testid="rate-form-grade"
          [value]="gradeInput()"
          (change)="gradeInput.set($any($event.target).value); error.set(null)"
        >
  status: ClaimStatus;
  by: string;
  date: string;
  due: string;
}

/** The date a claim's live figures round by: its own, or for a correction the date of the claim it
 *  corrects, found by number among `claims` (its own when that claim is not among them). */
export function roundingDate(c: Claim, claims: readonly Claim[]): string {
  if (!isCorrection(c) || c.corrects === null) return c.date;
  return claims.find((o) => o.number === c.corrects)?.date ?? c.date;
}

/** Whether a claim is a correction: its amount is below zero. */
export function isCorrection(c: Claim): boolean {
  return cents(c.amount) < 0;
}

/** Another person a claim can be moved to. */
export interface ClaimTarget {
  id: number;
  name: string;
}

/** A move from one status to the next, by the endpoint that makes it. */
type ClaimAction = 'open' | 'settle' | 'resettle' | 'approve' | 'reject' | 'void' | 'delete' | 'restore';

/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do (a correction never toward claimed). */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/** The status a claim had at the end of a day (yyyy-mm-dd), as its status log records it (the last
 *  line logged on or before it); null when it had none yet. */
export function statusAt(c: Claim, day: string): ClaimStatus | null {
  let at: ClaimStatus | null = null;
  for (const l of c.log) if (l.date <= day) at = l.status;
  return at;
}

/** Whether a claim is open: OPEN or PENDING. Only an open claim goes overdue, and a hold takes it out of the totals. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim is deferred on the sheet's today: open, and its deferral date not yet reached. */
export function deferred(c: Claim, today: string | null): boolean {
  return isOpen(c) && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** The refusal of a change to a claim dated inside a closed period. */
const CLOSED = 'That date is inside a closed period.';

/** The refusal of editing a claim another user's open editor locks (or no longer a DRAFT). */
const LOCKED = 'Another user is editing this claim, or it is no longer a DRAFT.';

/** The refusal of a correction that names no SETTLED claim of its person. */
const UNCORRECTABLE = 'A negative amount must correct a SETTLED claim of this person, by its number.';

const PAST: Record<ClaimAction, string> = {
  open: 'opened',
  settle: 'settled',
  resettle: 're-settled',
  approve: 'approved',
  reject: 'rejected',
  void: 'voided',
  delete: 'deleted',
  restore: 'restored',
};

/** A reason for rejecting a claim: one word. */
const REASON = /^\S{1,200}$/;

/** An amount: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;

/** A claim's amount: as {@link AMOUNT}, or below zero for a correction. */
const SIGNED_AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;

/** A claim number: a whole number from 1, or a period's (or X) with its number in it, as <name>-<n>. */
const NUMBER = /^(.{1,100}-)?[1-9]\d{0,8}$/;

/** An amount in whole cents, so sums are exact; below zero for a negative amount. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const c = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  return negative ? -c : c;
}

/** Days since 1970-01-01 of a yyyy-mm-dd date (proleptic Gregorian). */
export function dayNumber(date: string): number {
  const [y0, m, d] = date.split('-').map(Number);
  const y = m <= 2 ? y0 - 1 : y0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** The yyyy-mm-dd date a number of days after a yyyy-mm-dd date (proleptic Gregorian). */
export function plusDays(date: string, days: number): string {
  const z = dayNumber(date) + days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp < 10 ? mp + 3 : mp - 9;
  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

/** The date a claim is due by: fixed when it was added. */
export function dueBy(c: Claim): string {
  return c.dueBy;
}

/** Whether a claim is overdue: open (OPEN or PENDING), not deferred, and due by a date that, with
 *  the grace days of its person's grade added, is before the sheet's today. */
export function overdue(c: Claim, today: string | null, grace = 0): boolean {
  return isOpen(c) && !deferred(c, today) && today !== null && plusDays(dueBy(c), grace) < today;
}

/** The days a claim is overdue on the sheet's today: past its due-by plus its grace days; 0 when it is not overdue. */
export function daysOverdue(c: Claim, today: string | null, grace = 0): number {
  return overdue(c, today, grace) && today !== null ? dayNumber(today) - dayNumber(dueBy(c)) - grace : 0;
}

/** Whole cents shown with two decimals, with a minus sign below zero. */
export function money(c: number): string {
  const a = Math.abs(c);
  return `${c < 0 ? '-' : ''}${Math.floor(a / 100)}.${String(a % 100).padStart(2, '0')}`;
}

@Component({
  selector: 'app-person-claims',
  template: `
    <form [attr.aria-label]="'Claim for ' + personName()" (submit)="save($event)">
      <label [for]="'claim-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-amount-' + personId()"
        data-testid="claim-form-amount"
        inputmode="decimal"

/** A date as the date input gives it: yyyy-mm-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The period whose dates contain a date (yyyy-mm-dd), if any. */
export function periodOn(periods: readonly Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** A closed period's due-total fixed when it was closed; an open period's, the due of the claims
 *  whose due-by falls in it that counted at the end of its to-date. */
export function periodDueTotal(p: Period, dues: readonly DatedDue[]): string {
  if ((p.closed || p.softClosed) && p.closedDue !== null) return p.closedDue;
  return money(dues.reduce((sum, d) => sum + (inPeriod(p, d) ? d.cents : 0), 0));
}

/** A person's due-total for a period: for a closed period, the one fixed when it was closed (0.00
 *  for a person added since); for an open one, the due of their claims that counted in it at its end. */
export function personPeriodDueTotal(p: Period, personId: number, dues: readonly DatedDue[]): string {
  if ((p.closed || p.softClosed) && p.closedDues !== null) return p.closedDues[String(personId)] ?? '0.00';
  return money(
    dues.reduce((sum, d) => sum + (d.personId === personId && inPeriod(p, d) ? d.cents : 0), 0),
  );
}

/** Whether a date (yyyy-mm-dd) falls inside a closed period. */
export function inClosedPeriod(periods: readonly Period[], date: string): boolean {
  return periodOn(periods, date)?.closed ?? false;
}

