  protected readonly settledOpenTotals = computed(() => {
    const each = this.people().map((p) => this.settledOpenOf(p));
    return {
      settled: each.reduce((sum, t) => sum + t.settled, 0),
      open: each.reduce((sum, t) => sum + t.open, 0),
